/* @autogenerated */
import { Component, signal, viewChild } from '@angular/core';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { ContextFields } from '@shared/data/repository/context-filter';
import { BaseEditable } from './base-editable';
import { ContextUse, SubFormEditable } from './subform-editable';

const NO_CONTEXT: ContextFields = { fixed: {}, defaults: {}, filtered: [] };
const context = signal<ContextFields>(NO_CONTEXT);
let use: ContextUse = 'edit';
let fixture: ComponentFixture<HostComponent>;

@Component({
  selector: 'test-subform',
  template: '',
  providers: BaseEditable.getValidableAccessorProvider(TestSubFormComponent),
})
class TestSubFormComponent extends SubFormEditable<any> {
  constructor() {
    super(
      new FormGroup({
        client: new FormControl<any>(null),
        clients: new FormControl<any>(null),
        name: new FormControl<string>(''),
      }),
    );
    this.useContext(context, use);
    this.defaultValues = () => ({ client: null, clients: null, name: '' });
  }
}

@Component({
  imports: [ReactiveFormsModule, TestSubFormComponent],
  template: '<test-subform [formControl]="control" />',
})
class HostComponent {
  control = new FormControl<any>(null);
  sub = viewChild.required(TestSubFormComponent);
}

describe('SubFormEditable context', () => {
  afterEach(() => {
    context.set(NO_CONTEXT);
    use = 'edit';
    TestBed.resetTestingModule();
  });

  async function setup(value: any = null) {
    TestBed.configureTestingModule({
      imports: [
        TranslocoTestingModule.forRoot({ langs: {}, translocoConfig: { availableLangs: ['es'], defaultLang: 'es' } }),
      ],
    });
    fixture = TestBed.createComponent(HostComponent);
    fixture.componentInstance.control.setValue(value);
    fixture.detectChanges();
    await fixture.whenStable();
    fixture.detectChanges();
    return fixture.componentInstance.sub();
  }

  it('fills, locks and hides the fixed fields when editing', async () => {
    context.set({ fixed: { client: { $ref: 'c1' } }, defaults: {}, filtered: ['client', 'clients'] });
    const sub = await setup({ client: { $ref: 'other' }, name: 'n' });

    expect(sub.form.getRawValue().client).toEqual({ $ref: 'c1' });
    expect(sub.form.controls['client'].disabled).toBeTrue();
    expect(sub.isVisible['client']).toBeFalse();
    expect(sub.isVisible['name']).toBeTrue();
  });

  it('fills only the empty fields with default values', async () => {
    context.set({ fixed: {}, defaults: { client: { $ref: 'c1' } }, filtered: [] });
    expect((await setup(null)).form.getRawValue().client).toEqual({ $ref: 'c1' });

    TestBed.resetTestingModule();
    expect((await setup({ client: { $ref: 'mine' } })).form.getRawValue().client).toEqual({ $ref: 'mine' });
  });

  it('hides in a search the filters the context already applies, without filling them', async () => {
    use = 'search';
    context.set({ fixed: { client: { $ref: 'c1' } }, defaults: {}, filtered: ['client', 'clients'] });
    const sub = await setup(null);

    expect(sub.form.getRawValue().client).toBeNull();
    expect(sub.isVisible['client']).toBeFalse();
    expect(sub.isVisible['clients']).toBeFalse();
  });

  it('follows context changes', async () => {
    const sub = await setup({ name: 'n' });
    expect(sub.isVisible['client']).toBeTrue();

    context.set({ fixed: { client: { $ref: 'c2' } }, defaults: {}, filtered: ['client'] });
    fixture.detectChanges();
    await fixture.whenStable();

    expect(sub.form.getRawValue().client).toEqual({ $ref: 'c2' });
    expect(sub.isVisible['client']).toBeFalse();
  });
});

@Component({
  selector: 'test-required-subform',
  template: '',
  providers: BaseEditable.getValidableAccessorProvider(RequiredSubFormComponent),
})
class RequiredSubFormComponent extends SubFormEditable<any> {
  constructor() {
    super(
      new FormGroup({
        name: new FormControl<string>('', [Validators.required]),
        code: new FormControl<string>(''),
      }),
    );
  }
}

@Component({
  imports: [ReactiveFormsModule, RequiredSubFormComponent],
  template: `<test-required-subform
    [formControl]="control"
    [fixed]="fixed()"
    [hidden]="hidden()"
    [defined]="defined()"
  />`,
})
class InputsHostComponent {
  control = new FormControl<any>(null);
  fixed = signal<string[]>([]);
  hidden = signal<string[]>([]);
  defined = signal<Record<string, any> | undefined>(undefined);
  sub = viewChild.required(RequiredSubFormComponent);
}

describe('SubFormEditable inputs', () => {
  let host: ComponentFixture<InputsHostComponent>;

  const settle = async () => {
    host.detectChanges();
    await new Promise((resolve) => setTimeout(resolve));
    host.detectChanges();
  };

  beforeEach(async () => {
    TestBed.configureTestingModule({
      imports: [
        TranslocoTestingModule.forRoot({ langs: {}, translocoConfig: { availableLangs: ['es'], defaultLang: 'es' } }),
      ],
    });
    host = TestBed.createComponent(InputsHostComponent);
    await settle();
  });

  afterEach(() => TestBed.resetTestingModule());

  it('disables the fixed fields and enables them again', async () => {
    host.componentInstance.fixed.set(['code']);
    await settle();
    const sub = host.componentInstance.sub();
    expect(sub.form.get('code')!.disabled).toBeTrue();
    expect(sub.isEditable['code']).toBeFalse();

    host.componentInstance.fixed.set([]);
    await settle();
    expect(sub.form.get('code')!.enabled).toBeTrue();
  });

  it('disables every field when the outer control is disabled', async () => {
    host.componentInstance.control.disable();
    host.componentInstance.fixed.set(['code']);
    await settle();

    expect(host.componentInstance.sub().form.get('name')!.disabled).toBeTrue();
  });

  it('hides the hidden fields', async () => {
    host.componentInstance.hidden.set(['name']);
    await settle();

    expect(host.componentInstance.sub().isVisible).toEqual({ name: false, code: true });
  });

  it('fills the defined values over the outer value and drops unknown fields', async () => {
    host.componentInstance.defined.set({ code: 'C1' });
    await settle();

    host.componentInstance.control.setValue({ name: 'Ana', other: 'x' });
    await settle();

    expect(host.componentInstance.sub().form.getRawValue()).toEqual({ name: 'Ana', code: 'C1' });
  });

  it('keeps the value of a fixed field missing in the outer value', async () => {
    const sub = host.componentInstance.sub();
    sub.form.get('code')!.setValue('kept');
    host.componentInstance.fixed.set(['code']);
    await settle();

    host.componentInstance.control.setValue({ name: 'Ana' });
    await settle();

    expect(sub.form.getRawValue()).toEqual({ name: 'Ana', code: 'kept' });
  });

  it('sends its value up and names the errors of its fields', async () => {
    const sub = host.componentInstance.sub();
    sub.form.get('code')!.setValue('X');
    sub.form.markAsDirty();
    sub.form.get('name')!.setValue('');
    await settle();

    expect(host.componentInstance.control.value).toEqual({ name: '', code: 'X' });
    expect((sub as any).errors()).toEqual({ 'name.required': true });
  });

  it('starts from empty default values', () => {
    expect(host.componentInstance.sub().defaultValues()).toEqual({});
  });
});
